//! Bitmap (`SHOT`) replay of the original `UViewport::Exec` screenshot path.
//!
//! `fixtures/camera_bitmap.txt` was generated by `Build/camera_fixture_harness/camera_exec_harness.cpp`
//! from `UnCamera.cpp` at 69c3263. Each record builds the same fake object graph as the harness,
//! runs the Rust `camera_exec::exec` on its `SHOT` command, and compares the recorded trace
//! (`CMD`, `READPIX`, `CREATE`, `FILE`, `RET`, `STATE`) line by line with the fixture. The `FILE`
//! line carries the complete bitmap bytes, so the header and pixel bytes are checked exactly.
//! Any camera service the replay does not model panics (fail-fast).

use std::cell::{Cell, RefCell};
use std::collections::HashMap;
use std::ffi::c_void;
use std::mem::size_of;

use hp2_abi::FColor;
use hp2_abi::engine::generated::{APlayerPawn, UViewport};
use hp2_engine::camera::CameraServices;
use hp2_engine::camera_exec::{exec, render_dev_exec};
use hp2_engine::params::TChar;

const FIXTURE: &str = include_str!("fixtures/camera_bitmap.txt");
const BITMAP_CASES: usize = 6;
/// Family code the harness passes to `seed()` for bitmap records.
const FAMILY_BITMAP: u32 = 1;

// Non-dereferenced identity tokens for the C++ objects. Only their addresses are compared.
static SENT: [u8; 96] = [0; 96];
const AR_OFF: usize = 0;
const INPUT_OFF: usize = 48;
const RD_OFF: usize = 64;

fn sentinel(off: usize) -> *mut c_void {
    SENT.as_ptr().wrapping_add(off) as *mut c_void
}

/// Per-case state read by the fakes. The trace is the replay output.
#[derive(Default)]
struct World {
    trace: Vec<String>,
    lcg: u32,
    size_x: i32,
    size_y: i32,
    rd: bool,
    detail: i32,
    /// Level actors: `Some(true)` is a hidden actor, `None` is a NULL entry.
    level: Vec<Option<bool>>,
}

thread_local! {
    static WORLD: RefCell<World> = RefCell::new(World::default());
    static SERVICES: Cell<*const CameraServices> = const { Cell::new(std::ptr::null()) };
}

fn emit(line: String) {
    WORLD.with(|w| w.borrow_mut().trace.push(line));
}

fn next_u32() -> u32 {
    WORLD.with(|w| {
        let mut w = w.borrow_mut();
        w.lcg = w.lcg.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        w.lcg
    })
}

fn seed(family: u32, idx: usize) {
    let value = 0x2545_F491u32
        .wrapping_add(1000u32.wrapping_mul(family))
        .wrapping_add(idx as u32);
    WORLD.with(|w| w.borrow_mut().lcg = value);
}

fn units(s: &str) -> Vec<u32> {
    s.chars().map(|c| c as u32).collect()
}

fn units_str(u: &[u32]) -> String {
    u.iter()
        .map(|&c| char::from_u32(c).unwrap_or('?'))
        .collect()
}

/// Harness `esc`: `\r` and `\n` as escapes, `"` as `'`, other non-printables as `?`.
fn esc(u: &[u32]) -> String {
    let mut out = String::new();
    for &c in u {
        match c {
            0x0d => out.push_str("\\r"),
            0x0a => out.push_str("\\n"),
            0x22 => out.push('\''),
            c if !(32..=126).contains(&c) => out.push('?'),
            c => out.push(char::from(c as u8)),
        }
    }
    out
}

/// Reads a NUL-terminated TCHAR string as code units.
///
/// # Safety
/// `p` must point to a NUL-terminated TCHAR string.
unsafe fn read_units(p: *const c_void) -> Vec<u32> {
    let mut q = p as *const TChar;
    let mut out = Vec::new();
    unsafe {
        while *q != 0 {
            out.push(*q as u32);
            q = q.add(1);
        }
    }
    out
}

fn tchars(s: &str) -> Vec<TChar> {
    s.chars()
        .map(|c| c as u32 as TChar)
        .chain(std::iter::once(0))
        .collect()
}

fn is_blank(c: u32) -> bool {
    c == 0x20 || c == 0x09
}

fn is_alnum(c: u32) -> bool {
    (0x30..=0x39).contains(&c) || (0x41..=0x5a).contains(&c) || (0x61..=0x7a).contains(&c)
}

fn fold_case(c: u32) -> u32 {
    if (0x41..=0x5a).contains(&c) {
        c + 0x20
    } else {
        c
    }
}

/// Harness `ParseCommand`: a case-insensitive keyword at a word boundary; advances the cursor on match.
///
/// # Safety
/// `slot` must point to a valid `*const TChar` cursor; `token` to a NUL-terminated TCHAR string.
unsafe fn match_command(slot: *mut *const TChar, token: *const c_void) -> i32 {
    unsafe {
        let want = read_units(token);
        let mut p = *slot;
        while is_blank(*p as u32) {
            p = p.add(1);
        }
        let matched = want
            .iter()
            .enumerate()
            .all(|(i, &w)| fold_case(*p.add(i) as u32) == fold_case(w));
        let end = p.add(want.len());
        if matched && !is_alnum(*end as u32) {
            let mut q = end;
            while is_blank(*q as u32) {
                q = q.add(1);
            }
            *slot = q;
            return 1;
        }
        0
    }
}

/// Harness `ParseToken` without escapes: a blank-delimited or quoted token, bounded by `max`.
///
/// # Safety
/// `slot` must point to a valid `*const TChar` cursor; `buf` must hold `max` TCHARs.
unsafe fn match_token(slot: *mut *const TChar, buf: *mut TChar, max: i32) -> i32 {
    unsafe {
        let max = max.max(0) as usize;
        let mut p = *slot;
        while is_blank(*p as u32) {
            p = p.add(1);
        }
        let mut len = 0usize;
        if *p as u32 == 0x22 {
            p = p.add(1);
            while *p != 0 && *p as u32 != 0x22 && len + 1 < max {
                *buf.add(len) = *p;
                len += 1;
                p = p.add(1);
            }
            if *p as u32 == 0x22 {
                p = p.add(1);
            }
        } else {
            while *p != 0 && !is_blank(*p as u32) {
                if len + 1 < max {
                    *buf.add(len) = *p;
                    len += 1;
                }
                p = p.add(1);
            }
        }
        if max > 0 {
            *buf.add(len) = 0;
        }
        *slot = p;
        (len != 0) as i32
    }
}

unsafe extern "C" fn unexpected_service() {
    panic!("camera_bitmap replay reached a camera service the SHOT fixture does not model");
}

unsafe extern "C" fn parse_command(cursor: *mut c_void, token: *const c_void) -> i32 {
    unsafe { match_command(cursor as *mut *const TChar, token) }
}

unsafe extern "C" fn parse_token(cursor: *mut c_void, buf: *mut c_void, len: i32) -> i32 {
    unsafe { match_token(cursor as *mut *const TChar, buf as *mut TChar, len) }
}

/// Delegates to the Rust port, as the production C++ -> Rust wiring does.
unsafe extern "C" fn render_dev_exec_fake(
    rd: *mut c_void,
    cmd: *const c_void,
    ar: *mut c_void,
) -> i32 {
    let svc = SERVICES.with(|c| c.get());
    assert!(!svc.is_null(), "services pointer is set before replay");
    unsafe { render_dev_exec(&*svc, rd, cmd, ar) }
}

/// `UViewport::Exec`'s `RenDev->ReadPixels`: one LCG step per pixel, reset per case.
unsafe extern "C" fn read_pixels(_rd: *mut c_void, dest: *mut c_void) {
    let (w, h) = WORLD.with(|w| {
        let w = w.borrow();
        (w.size_x, w.size_y)
    });
    emit(format!("  READPIX {w}x{h}"));
    let out = dest as *mut FColor;
    for i in 0..(w * h) as usize {
        let v = next_u32();
        let px = FColor {
            r: (v & 255) as u8,
            g: ((v >> 8) & 255) as u8,
            b: ((v >> 16) & 255) as u8,
            a: ((v >> 24) & 255) as u8,
        };
        unsafe { *out.add(i) = px };
    }
}

/// Bitmap archive: captures the serialized bytes, printed on delete.
struct Archive {
    path: String,
    bytes: Vec<u8>,
}

fn create_archive(path: &str) -> *mut c_void {
    let p = esc(&units(path));
    emit(format!("  CREATE \"{p}\""));
    Box::into_raw(Box::new(Archive {
        path: p,
        bytes: Vec::new(),
    })) as *mut c_void
}

/// `CreateFileWriter(SaveSlotPath * file)`: the harness sets `SaveSlotPath` to `Slot\`.
unsafe extern "C" fn create_slot_file_writer(file: *const c_void) -> *mut c_void {
    let name = units_str(&unsafe { read_units(file) });
    create_archive(&format!("Slot\\/{name}"))
}

unsafe extern "C" fn archive_serialize(ar: *mut c_void, data: *const c_void, count: i32) {
    if count <= 0 {
        return;
    }
    unsafe {
        let src = std::slice::from_raw_parts(data as *const u8, count as usize);
        let arc = &mut *(ar as *mut Archive);
        arc.bytes.extend_from_slice(src);
    }
}

unsafe extern "C" fn archive_delete(ar: *mut c_void) {
    let arc = unsafe { Box::from_raw(ar as *mut Archive) };
    let hex: String = arc.bytes.iter().map(|b| format!("{b:02x}")).collect();
    emit(format!(
        "  FILE \"{}\" n={} {hex}",
        arc.path,
        arc.bytes.len()
    ));
}

fn services() -> CameraServices {
    const WORDS: usize = size_of::<CameraServices>() / size_of::<usize>();
    let filler = unexpected_service as unsafe extern "C" fn() as usize;
    let table: [usize; WORDS] = [filler; WORDS];
    // SAFETY: every field of `CameraServices` is a function pointer, so the table has the
    // struct's exact layout. Unused entries point at `unexpected_service`.
    let mut svc: CameraServices = unsafe { std::mem::transmute(table) };
    svc.parse_command = parse_command;
    svc.parse_token = parse_token;
    svc.render_dev_exec = render_dev_exec_fake;
    svc.render_dev_read_pixels = read_pixels;
    svc.create_slot_file_writer = create_slot_file_writer;
    svc.archive_serialize = archive_serialize;
    svc.archive_delete = archive_delete;
    svc
}

/// Harness `print_state`.
fn state_line(vp: &UViewport, pawn: &APlayerPawn) -> String {
    let (show, rend, hidden) = if vp.actor.is_null() {
        (0u32, -1, 0usize)
    } else {
        let hidden = WORLD.with(|w| {
            w.borrow()
                .level
                .iter()
                .filter(|a| **a == Some(true))
                .count()
        });
        (pawn.show_flags as u32, pawn.rend_map, hidden)
    };
    let (rd, detail) = WORLD.with(|w| {
        let w = w.borrow();
        (w.rd, w.detail)
    });
    let detail = if rd { detail } else { -1 };
    let n = vp.snap_buff.num;
    let fnv = if n > 0 {
        // SAFETY: the snap buffer holds `num` FColor entries.
        let px =
            unsafe { std::slice::from_raw_parts(vp.snap_buff.data as *const FColor, n as usize) };
        px.iter()
            .flat_map(|c| [c.r, c.g, c.b, c.a])
            .fold(0x811c_9dc5u32, |h, b| {
                (h ^ b as u32).wrapping_mul(16_777_619)
            })
    } else {
        0x811c_9dc5
    };
    format!(
        "  STATE show={show:08x} rend={rend} hidden={hidden} detail={detail} snap={}x{} n={n} fnv={fnv:08x} dragging={} hitsizes={} frame={} render={:08x} extra={:08x} hit={}",
        vp.snap_u,
        vp.snap_v,
        vp.dragging,
        vp.hit_sizes.num,
        vp.frame_count as u32,
        vp.render_flags,
        vp.extra_poly_flags,
        vp.hit_testing,
    )
}

/// One parsed fixture record.
struct Case {
    idx: usize,
    kv: HashMap<String, String>,
    cmds: Vec<String>,
    expect: Vec<String>,
}

impl Case {
    fn num(&self, key: &str) -> i64 {
        let v = self
            .kv
            .get(key)
            .unwrap_or_else(|| panic!("bitmap case {} lacks {key}=", self.idx));
        v.parse()
            .unwrap_or_else(|_| panic!("bitmap case {} {key}={v} is not decimal", self.idx))
    }
}

fn parse_header(rest: &str) -> Case {
    let (head, cmds) = rest
        .split_once(" cmds=")
        .expect("bitmap case header carries cmds=");
    let mut fields = head.split_whitespace();
    let family = fields.next().expect("bitmap case family");
    assert_eq!(
        family, "bitmap",
        "camera_bitmap.txt holds only bitmap records"
    );
    let idx = fields
        .next()
        .expect("bitmap case index")
        .parse::<usize>()
        .expect("bitmap case index is numeric");
    let kv = fields
        .map(|f| {
            let (k, v) = f.split_once('=').expect("bitmap knob is key=value");
            (k.to_string(), v.to_string())
        })
        .collect();
    let cmds = if cmds == "-" {
        Vec::new()
    } else {
        cmds.split('|').map(str::to_string).collect()
    };
    Case {
        idx,
        kv,
        cmds,
        expect: Vec::new(),
    }
}

fn parse_fixture() -> Vec<Case> {
    let mut out: Vec<Case> = Vec::new();
    for line in FIXTURE.lines() {
        if let Some(rest) = line.strip_prefix("case ") {
            out.push(parse_header(rest));
        } else if line.starts_with("  ") {
            let case = out.last_mut().expect("trace line before any case header");
            case.expect.push(line.trim_end().to_string());
        }
    }
    out
}

/// Replays one record and returns its trace.
fn replay(case: &Case) -> Vec<String> {
    let size_x = case.num("w") as i32;
    let size_y = case.num("h") as i32;
    let show = case.num("show") as i32;
    let rend = case.num("rend") as i32;
    let actor = case.num("actor") != 0;
    let rd = case.num("rd") != 0;

    WORLD.with(|w| {
        *w.borrow_mut() = World {
            size_x,
            size_y,
            rd,
            detail: case.num("detail") as i32,
            level: if actor {
                vec![Some(true), None, Some(true)]
            } else {
                Vec::new()
            },
            ..World::default()
        };
    });
    seed(FAMILY_BITMAP, case.idx);

    let mut pawn: APlayerPawn = unsafe { std::mem::zeroed() };
    pawn.show_flags = show;
    pawn.rend_map = rend;
    let mut vp: UViewport = unsafe { std::mem::zeroed() };
    vp.size_x = size_x;
    vp.size_y = size_y;
    if actor {
        vp.actor = &mut pawn as *mut APlayerPawn as *mut c_void;
    }
    if case.num("in") >= 0 {
        vp.input = sentinel(INPUT_OFF);
    }
    if rd {
        vp.ren_dev = sentinel(RD_OFF);
    }

    let svc = services();
    SERVICES.with(|c| c.set(&svc as *const CameraServices));
    for cmd in &case.cmds {
        emit(format!("  CMD \"{cmd}\""));
        let buf = tchars(cmd);
        let r = unsafe {
            exec(
                &svc,
                &mut vp,
                buf.as_ptr() as *const c_void,
                sentinel(AR_OFF),
            )
        }
        .expect("bitmap exec returned a fault");
        emit(format!("  RET {r}"));
    }
    emit(state_line(&vp, &pawn));
    WORLD.with(|w| std::mem::take(&mut w.borrow_mut().trace))
}

#[test]
fn camera_bitmap_fixture_replays_bit_exact() {
    let cases = parse_fixture();
    assert_eq!(
        cases.len(),
        BITMAP_CASES,
        "camera_bitmap.txt holds {BITMAP_CASES} bitmap records"
    );
    let mut matched = 0usize;
    for case in &cases {
        let got = replay(case);
        assert_eq!(
            got, case.expect,
            "bitmap case {} diverged from the C++ fixture",
            case.idx
        );
        matched += 1;
    }
    assert_eq!(matched, BITMAP_CASES, "every bitmap record matched");
}
